    const fd = await open(temp, 'wx');
    try { await fd.writeFile(JSON.stringify(lock)); await fd.sync(); } finally { await fd.close(); }
    try {
      // Exclusive publication of complete metadata avoids half-written lock files.
      await link(temp, path);
